import crypto from 'node:crypto';
import mongoose from 'mongoose';
import { Order, Ticket, Lottery, Notification, User } from '../models/index.js';
import { sendTelegram } from '../bot/index.js';
import { tr } from '../i18n.js';
import { deleteUpload } from '../api/files.js';

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
export function newOrderCode() {
  let s = '';
  for (let i = 0; i < 10; i++) s += ALPHABET[crypto.randomInt(ALPHABET.length)];
  return s;
}

export class ApiError extends Error {
  constructor(status, code, extra = {}) {
    super(code);
    this.statusCode = status;
    this.code = code;
    this.extra = extra;
  }
}

export const fmtNumbers = (arr) => arr.map((n) => `#${n}`).join(', ');

async function takenAmong(lotteryId, numbers) {
  const rows = await Ticket.find({ lottery: lotteryId, number: { $in: numbers } }).select('number');
  return rows.map((r) => r.number).sort((a, b) => a - b);
}

// Creates a PENDING order and HOLDS the numbers.
// The unique index (lottery + number) guarantees only the first order gets a number.
export async function createOrder({ user, lottery, numbers, fullName, bankId, senderAccount, receiptUrl }) {
  const orderId = new mongoose.Types.ObjectId();
  const order = new Order({
    _id: orderId,
    code: newOrderCode(),
    user: user.telegramId,
    lottery: lottery._id,
    fullName,
    phone: user.phone,
    bankAccount: bankId || null,
    senderAccount: senderAccount || undefined,
    receiptUrl,
    total: numbers.length * lottery.ticketPrice,
  });
  await order.save();

  try {
    await Ticket.insertMany(
      numbers.map((number) => ({
        lottery: lottery._id,
        number,
        order: orderId,
        user: user.telegramId,
        status: 'HELD',
      })),
      { ordered: false }
    );
  } catch (e) {
    // Someone else got there first: undo everything for this order
    await Ticket.deleteMany({ order: orderId });
    await Order.deleteOne({ _id: orderId });
    if (e?.code === 11000 || e?.writeErrors || e?.name === 'MongoBulkWriteError') {
      const taken = await takenAmong(lottery._id, numbers);
      throw new ApiError(409, 'numbers_taken', { taken });
    }
    throw e;
  }
  return order;
}

export async function preCheckNumbers(lotteryId, numbers) {
  const taken = await takenAmong(lotteryId, numbers);
  if (taken.length) throw new ApiError(409, 'numbers_taken', { taken });
}

async function notify(order, build) {
  const user = await User.findOne({ telegramId: order.user });
  const lang = user?.language || 'en';
  const { title, body } = build(tr(lang));
  await Notification.create({ user: order.user, title, body });
  await sendTelegram(order.user, `${title}\n\n${body}`);
}

export async function approveOrder(orderId) {
  const order = await Order.findOneAndUpdate(
    { _id: orderId, status: 'PENDING' },
    { status: 'APPROVED', reviewedAt: new Date() },
    { returnDocument: "after" }
  );
  if (!order) throw new ApiError(409, 'order_not_pending');
  await Ticket.updateMany({ order: order._id }, { status: 'TAKEN' });
  const nums = (await Ticket.find({ order: order._id }).select('number'))
    .map((t) => t.number)
    .sort((a, b) => a - b);
  await notify(order, (x) => ({ title: x.approvedTitle, body: x.approvedBody(order.code, fmtNumbers(nums)) }));
  return order;
}

export async function rejectOrder(orderId, reason) {
  const order = await Order.findOneAndUpdate(
    { _id: orderId, status: 'PENDING' },
    { status: 'REJECTED', reviewedAt: new Date(), rejectReason: reason || undefined },
    { returnDocument: "after" }
  );
  if (!order) throw new ApiError(409, 'order_not_pending');
  await Ticket.deleteMany({ order: order._id }); // numbers become free again
  await notify(order, (x) => ({ title: x.rejectedTitle, body: x.rejectedBody(order.code, reason) }));
  return order;
}

// Picks one winner at random among TAKEN tickets (cryptographically secure)
export async function drawWinner(lotteryId) {
  const lottery = await Lottery.findById(lotteryId);
  if (!lottery) throw new ApiError(404, 'not_found');
  if (lottery.status === 'DRAWN') throw new ApiError(409, 'already_drawn');
  const pending = await Order.countDocuments({ lottery: lottery._id, status: 'PENDING' });
  if (pending) throw new ApiError(409, 'pending_orders_exist', { pending });

  const total = await Ticket.countDocuments({ lottery: lottery._id, status: 'TAKEN' });
  if (!total) throw new ApiError(409, 'no_tickets');
  const winner = await Ticket.findOne({ lottery: lottery._id, status: 'TAKEN' })
    .sort({ number: 1 })
    .skip(crypto.randomInt(total));

  lottery.status = 'DRAWN';
  lottery.winnerNumber = winner.number;
  lottery.winnerUser = winner.user;
  lottery.drawnAt = new Date();
  await lottery.save();

  const user = await User.findOne({ telegramId: winner.user });
  const x = tr(user?.language || 'en');
  const title = x.winnerTitle;
  const body = x.winnerBody(lottery.title, winner.number);
  await Notification.create({ user: winner.user, title, body });
  await sendTelegram(winner.user, `${title}\n\n${body}`);
  return lottery;
}

export async function removeOrderFile(order) {
  await deleteUpload(order.receiptUrl);
}
